std::vector<int> merge_sort(std::vector<int> a) {
    if (a.size() <= 1) return a;
    auto mid = a.begin() + a.size() / 2;
    auto L = merge_sort({a.begin(), mid});
    auto R = merge_sort({mid, a.end()});
    std::vector<int> out;
    out.reserve(a.size());
    std::merge(L.begin(), L.end(), R.begin(), R.end(), std::back_inserter(out));
    return out;
}

int main() {
