fn main() {
    // Ownership: `s1` is moved, not copied
    let s1 = String::from("ownership");
    let s2 = s1.clone();
    println!("s1 = {s1}, clone s2 = {s2}");

    // Borrowing: read-only references, as many as you like
    let len = calculate_length(&s2);
    println!("length of '{s2}' is {len}");

    // A mutable borrow — exactly one at a time
    let mut owned = String::from("hello");
    append_world(&mut owned);
    println!("after mutable borrow: {owned}");

    // Iterators are lazy and compose without allocating each step
    let squares: Vec<u32> = (1..=8).map(|n| n * n).filter(|n| n % 2 == 0).collect();
    println!("even squares: {squares:?}");

    // Result forces you to handle failure
    for text in ["42", "oops"] {
        match text.parse::<i32>() {
            Ok(n)  => println!("parsed {text} -> {n}"),
            Err(e) => println!("failed  {text} -> {e}"),
        }
    }
}

fn calculate_length(s: &String) -> usize { s.len() }

