package main

import (
	"fmt"
	"sync"
)

func main() {
	jobs := make(chan int, 10)
	results := make(chan string, 10)
	var wg sync.WaitGroup

	for w := 1; w <= 3; w++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			for n := range jobs {
				results <- fmt.Sprintf("worker %d squared %d = %d", id, n, n*n)
			}
		}(w)
	}

	for n := 1; n <= 6; n++ {
		jobs <- n
	}
	close(jobs)
	wg.Wait()
	close(results)

	count := 0
	for range results {
		count++
	}
	fmt.Printf("%d jobs completed by 3 workers\n", count)
}

# A DFA that accepts binary strings with an even number of 1s
delta = {
    ("even", "0"): "even", ("even", "1"): "odd",
    ("odd",  "0"): "odd",  ("odd",  "1"): "even",
}
start, accepting = "even", {"even"}

def run(word):
    state = start
    trace = [state]
    for ch in word:
        state = delta[(state, ch)]
        trace.append(state)
    return state in accepting, trace

for word in ["", "0", "11", "101", "1010", "111", "110011"]:
    ok, trace = run(word)
    path = " -> ".join(trace)
    print(f"{word or '(empty)':<9} {'ACCEPT' if ok else 'reject':<7} {path}")

print()
accepted = [w for w in ["", "0", "11", "101", "1010", "111", "110011"] if run(w)[0]]
print("accepted:", accepted)

import re

# A complete little language: tokenise, parse into a tree, then evaluate.
def tokenise(src):
    return re.findall(r"\d+\.?\d*|[()+\-*/]", src)

class Parser:
    def __init__(self, tokens):
        self.t, self.i = tokens, 0
    def peek(self):
        return self.t[self.i] if self.i < len(self.t) else None
    def take(self):
        tok = self.peek(); self.i += 1; return tok

    def expr(self):                      # expr := term (('+'|'-') term)*
        node = self.term()
        while self.peek() in ("+", "-"):
            node = (self.take(), node, self.term())
        return node
    def term(self):                      # term := atom (('*'|'/') atom)*
        node = self.atom()
        while self.peek() in ("*", "/"):
            node = (self.take(), node, self.atom())
        return node
    def atom(self):                      # atom := number | '(' expr ')'
        tok = self.take()
        if tok == "(":
            node = self.expr(); self.take(); return node
        return float(tok)

def evaluate(node):
    if isinstance(node, float):
        return node
    op, a, b = node
    a, b = evaluate(a), evaluate(b)
    return {"+": a+b, "-": a-b, "*": a*b, "/": a/b}[op]

for src in ["2 + 3 * 4", "(2 + 3) * 4", "10 / 4 - 1", "2 * (3 + 4) * 5"]:
    toks = tokenise(src)
    tree = Parser(toks).expr()
    print(f"{src:<18} tokens={len(toks):<3} = {evaluate(tree):g}")

import numpy as np

# A unit square in homogeneous coordinates (x, y, 1)
square = np.array([[0, 0, 1], [1, 0, 1], [1, 1, 1], [0, 1, 1]], dtype=float).T

def translate(tx, ty):
    return np.array([[1, 0, tx], [0, 1, ty], [0, 0, 1]], dtype=float)

def scale(sx, sy):
    return np.array([[sx, 0, 0], [0, sy, 0], [0, 0, 1]], dtype=float)

def rotate(deg):
    r = np.radians(deg)
    return np.array([[np.cos(r), -np.sin(r), 0],
                     [np.sin(r),  np.cos(r), 0],
                     [0, 0, 1]], dtype=float)

# Order matters: this reads right to left — scale, then rotate, then translate
M = translate(3, 2) @ rotate(45) @ scale(2, 2)
out = M @ square

print("corner        original        transformed")
for i in range(4):
    ox, oy = square[0, i], square[1, i]
    nx, ny = out[0, i], out[1, i]
    print(f"  {i}      ({ox:.1f}, {oy:.1f})      ({nx:7.3f}, {ny:7.3f})")

print(f"\ndeterminant = {np.linalg.det(M[:2, :2]):.3f}  (area scale factor)")

