import numpy as np

# Toy 4-dimensional 'embeddings' — real ones come from a model,
# but the retrieval maths is exactly this.
passages = {
    "Photosynthesis converts light into sugar.":  [0.9, 0.1, 0.0, 0.2],
    "Transformers use self-attention layers.":     [0.1, 0.95, 0.2, 0.1],
    "Mitochondria produce ATP in the cell.":       [0.85, 0.05, 0.1, 0.3],
    "Attention scales with sequence length.":      [0.05, 0.9, 0.35, 0.05],
}
query = np.array([0.08, 0.93, 0.25, 0.07])   # 'how does attention work?'

def cosine(a, b):
    return float(a @ b / (np.linalg.norm(a) * np.linalg.norm(b)))

ranked = sorted(
    ((cosine(query, np.array(v)), k) for k, v in passages.items()),
    reverse=True,
)

print("query: how does attention work?\n")
for rank, (score, text) in enumerate(ranked, 1):
    mark = "<- retrieved" if rank <= 2 else ""
    print(f"{rank}. {score:.4f}  {text} {mark}")

print("\ncontext handed to the model:")
for _, text in ranked[:2]:
    print("  -", text)
